                                                                                                                                                                                                                        const money = value =>
                                                                                                                                                                                                                          value.toLocaleString("pt-BR", {
                                                                                                                                                                                                                              style: "currency",
                                                                                                                                                                                                                                  currency: "BRL"
                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                    const grid = document.getElementById("product-grid");
                                                                                                                                                                                                                                    const cart = [];

                                                                                                                                                                                                                                    function renderProducts(filter = "todos") {
                                                                                                                                                                                                                                      const shown = products.filter(
                                                                                                                                                                                                                                          p => filter === "todos" || p.category === filter
                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                              grid.innerHTML = shown.map(p => `
                                                                                                                                                                                                                                                  <article class="product-card">
                                                                                                                                                                                                                                                        <div class="product-photo">
                                                                                                                                                                                                                                                                <img src="${p.image}" alt="Frasco de perfume ${p.name}" loading="lazy">
                                                                                                                                                                                                                                                                        <span class="tag">${p.tag}</span>
                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                    <div class="product-info">
                                                                                                                                                                                                                                                                                            <span class="product-category">
                                                                                                                                                                                                                                                                                                      ${p.brand} · ${p.category}
                                                                                                                                                                                                                                                                                                              </span>

                                                                                                                                                                                                                                                                                                                      <h3>${p.name}</h3>
                                                                                                                                                                                                                                                                                                                              <p>${p.desc}</p>

                                                                                                                                                                                                                                                                                                                                      <div class="product-bottom">
                                                                                                                                                                                                                                                                                                                                                <strong class="price">${money(p.price)}</strong>

                                                                                                                                                                                                                                                                                                                                                          <button class="add-button" data-add="${p.id}">
                                                                                                                                                                                                                                                                                                                                                                      + Adicionar à sacola
                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                  </article>
                                                                                                                                                                                                                                                                                                                                                                                                    `).join("");
                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                    function renderCart() {
                                                                                                                                                                                                                                                                                                                                                                                                      const items = document.getElementById("cart-items");

                                                                                                                                                                                                                                                                                                                                                                                                        const count = cart.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                            (sum, item) => sum + item.qty, 0
                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                const total = cart.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                    (sum, item) => sum + item.price * item.qty, 0
                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("cart-count").textContent = count;
                                                                                                                                                                                                                                                                                                                                                                                                                          document.getElementById("cart-total").textContent = money(total);

                                                                                                                                                                                                                                                                                                                                                                                                                            items.innerHTML = cart.length
                                                                                                                                                                                                                                                                                                                                                                                                                                ? cart.map(item => `
                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="cart-row">
                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong>${item.name}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <small>${item.qty} × ${money(item.price)}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button class="remove-item" data-remove="${item.id}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Remover
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `).join("")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : '<p class="empty-cart">Sua sacola está vazia.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  grid.addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const button = event.target.closest("[data-add]");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const product = products.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p => p.id === Number(button.dataset.add)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const existing = cart.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item => item.id === product.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (existing) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            existing.qty++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cart.push({ ...product, qty: 1 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      renderCart();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.textContent = "Adicionado ✓";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              button.textContent = "+ Adicionar à sacola";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, 1100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("cart-items")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const button = event.target.closest("[data-remove]");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!button) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const index = cart.findIndex(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    item => item.id === Number(button.dataset.remove)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (index >= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cart.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          renderCart();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll(".filter").forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              button.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.querySelectorAll(".filter").forEach(b => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        b.classList.remove("active");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.classList.add("active");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderProducts(button.dataset.filter);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const overlay = document.getElementById("cart-overlay");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("open-cart").addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        overlay.hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("close-cart").addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          overlay.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          overlay.addEventListener("click", event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (event.target === overlay) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                overlay.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("copy-order")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .addEventListener("click", async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const note = document.getElementById("copy-note");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!cart.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  note.textContent = "Adicione pelo menos um perfume à sacola.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const lines = cart.map(item =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `${item.qty}x ${item.name} — ${money(item.price * item.qty)}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const total = cart.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    (sum, item) => sum + item.price * item.qty, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const message =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Olá! Tenho interesse em fazer este pedido na Lairyanne Perfumes:\n" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lines.join("\n") +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "\nTotal: " + money(total);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await navigator.clipboard.writeText(message);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              note.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Resumo copiado! Agora é só colar e enviar para a loja.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                note.textContent = message;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.getElementById("year").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        new Date().getFullYear();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderProducts();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderCart();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        